"""Utilities for coverstore"""

import contextlib
import json
import mimetypes
import os
import random
import socket
import string
from io import IOBase as file
from urllib.parse import parse_qsl, unquote, unquote_plus, urlsplit, urlunsplit  # type: ignore[attr-defined]
from urllib.parse import urlencode as real_urlencode

import requests
import web

from openlibrary.coverstore import config, oldb

socket.setdefaulttimeout(10.0)


def safeint(value, default=None):
    """
    >>> safeint('1')
    1
    >>> safeint('x')
    >>> safeint('x', 0)
    0
    """
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def get_ol_url():
    return web.rstrips(config.ol_url, "/")


def ol_things(key, value):
    if oldb.is_supported():
        return oldb.query(key, value)
    else:
        query = {
            'type': '/type/edition',
            key: value,
            'sort': 'last_modified',
            'limit': 10,
        }
        try:
            d = {"query": json.dumps(query)}
            result = download(get_ol_url() + '/api/things?' + real_urlencode(d))
            result = json.loads(result)
            return result['result']
        except OSError:
            import traceback

            traceback.print_exc()
            return []


def ol_get(olkey):
    if oldb.is_supported():
